import re

_UNIT_PATTERN = (
    r'weeks|week|wks|wk|w|'
    r'days|day|d|'
    r'hours|hour|hrs|hr|h|'
    r'minutes|minute|mins|min|m|'
    r'seconds|second|secs|sec|s'
)

_COMPONENT_RE = re.compile(
    r'(\d+(?:\.\d+)?)\s*(' + _UNIT_PATTERN + r')', re.IGNORECASE
)

_ISO_RE = re.compile(
    r'P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?'
)

_CLOCK_RE = re.compile(r'(\d+):(\d+)(?::(\d+(?:\.\d+)?))?')

_UNIT_SECONDS = {
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
    'd': 86400, 'day': 86400, 'days': 86400,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
}


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration text must not be None")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # bare non-negative integer -> seconds
    if re.fullmatch(r'\d+', s):
        return int(s)

    # ISO 8601 duration
    iso_match = re.fullmatch(_ISO_RE, s)
    if iso_match:
        w, d, h, m, sec = iso_match.groups()
        if not any([w, d, h, m, sec]):
            raise ValueError(f"invalid ISO8601 duration: {text!r}")
        total = 0.0
        if w:
            total += float(w) * 604800
        if d:
            total += float(d) * 86400
        if h:
            total += float(h) * 3600
        if m:
            total += float(m) * 60
        if sec:
            total += float(sec)
        return round(total)

    # clock notation: hh:mm:ss or mm:ss
    clock_match = re.fullmatch(_CLOCK_RE, s)
    if clock_match:
        a, b, c = clock_match.groups()
        if c is not None:
            h, m, sec = int(a), int(b), float(c)
        else:
            h, m, sec = 0, int(a), float(b)
        total = h * 3600 + m * 60 + sec
        return round(total)

    # number+unit components, optionally separated by spaces
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        while pos < len(s) and s[pos] == ' ':
            pos += 1
        if pos >= len(s):
            break
        match = _COMPONENT_RE.match(s, pos)
        if not match:
            raise ValueError(f"cannot parse duration: {text!r}")
        num, unit = match.groups()
        unit_l = unit.lower()
        seconds_per_unit = _UNIT_SECONDS.get(unit_l)
        if seconds_per_unit is None:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(num) * seconds_per_unit
        found = True
        pos = match.end()

    if not found:
        raise ValueError(f"cannot parse duration: {text!r}")

    return round(total)

